const outs=await Promise.all(prs.map(n=>tools.exec_command({
  cmd:`gh pr view ${n} --repo entireio/entire-graph --json number,url,isDraft,headRefName,headRefOid,baseRefOid,mergeable,mergeStateStatus,reviewDecision,statusCheckRollup`,
