  cmd:`gh pr checks ${n} --repo entireio/entire-graph`,
  workdir:"/Users/thomi/Projects/entire-graph",
  yield_time_ms:10000,
  max_output_tokens:12000
})));
outs.forEach((r,i)=>text(`PR ${prs[i]} (exit ${r.exit_code})\n${r.output}`));

