func fastCFamilyStatementEnd(lines []string, start int) int {
	depth := 0
	for i := start; i < len(lines); i++ {
		depth += braceDelta(lines[i])
		if strings.Contains(lines[i], ";") && depth <= 0 {
			return i + 1
		}
		if depth <= 0 && strings.Contains(lines[i], "}") {
