    cmd: 'for pr in 45 48 53; do gh pr view "$pr" --json number,url,headRefName,headRefOid,mergeable,mergeStateStatus,isDraft,statusCheckRollup,reviewDecision; done',
    workdir: '/Users/thomi/Projects/entire-graph',
    yield_time_ms: 30000,
    max_output_tokens: 8000
  }),
  tools.exec_command({
    cmd: 'git status --short --branch',
    workdir: '/Users/thomi/Projects/entire-graph',
    yield_time_ms: 30000,
    max_output_tokens: 1000
  })
]);
for (let i = 0; i < results.length; i++) {
  text(JSON.stringify({index: i, exit_code: results[i].exit_code, output: results[i].output}));
